local OnlineRewardButton = Class('OnlineRewardButton')

function OnlineRewardButton:__init()
    self.handler = nil
    self.isEnter = false
    self.trans = nil
    self.targetDojo = nil
end

function OnlineRewardButton:__delete()
    self.handler = nil
    self.isEnter = false
    self.trans = nil
    self.targetDojo = nil
end

function OnlineRewardButton:GetNextData()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not playerComponent:IsOpenOnlineRewards() then
        self.targetDojo = nil
        return
    end
    ---@type PlayerDojo
    local playerDojo = playerComponent.playerDojo
    local unlockStatus = checkNumber(playerDojo.onlineTaskInfo.unlockStatus)
    local taskList = checkTable(playerDojo.onlineTaskInfo.taskList)
    self.targetDojo = nil
    if unlockStatus == 1 and #taskList > 0 then
        ---存在合理数据时才进行倒计时
        for i, v in pairs(taskList) do
            ---未领取与可领取状态下
            if checkNumber(v.status) == 0 or checkNumber(v.status) == 1 then
                ---未领取
                self.targetDojo = v
                break
            end
        end
    end
    local isNextDraw = 0
    for i, v in pairs(taskList) do
        if checkNumber(v.type) == 2 and checkNumber(v.status) == 1 then
            ---可领取的状态下的逻辑
            isNextDraw = 1
            break
        end
    end
    if self.targetDojo then
        print('===>>', table.dump(self.targetDojo, false, 2))
        local status = checkNumber(self.targetDojo.status)
        local t = checkNumber(self.targetDojo.targetNum) - checkNumber(self.targetDojo.progress)
        t = math.max(0, t)
        if checkNumber(self.targetDojo.type) == 2 then
            CfUtils.FillText(self.TextDesc, isNextDraw == 0 and localize('明日可领') or localize('点击领取'))
            ---大奖励状态
            CfUtils.SetActive(self.UIFX_Receive, status == 1)
            CfUtils.SetActive(self.redPoint, status == 1)
            CfUtils.SetActive(self.TextTime.transform.parent, false)
        else
            CfUtils.FillText(self.TextDesc, localize('在线奖励'))
            CfUtils.SetActive(self.UIFX_Receive, status == 1 or t == 0)
            CfUtils.SetActive(self.redPoint, status == 1 or t == 0)
            CfUtils.SetActive(self.TextTime.transform.parent, status == 0 and t > 0)
            if status == 0 then
                ---未领取下存在计时
                CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS(t))
            end
        end
    else
        CfUtils.FillText(self.TextDesc, localize('在线奖励'))
        CfUtils.SetActive(self.UIFX_Receive, false)
        CfUtils.SetActive(self.redPoint, false)
        CfUtils.SetActive(self.TextTime.transform.parent, false)
    end
end

