function OnlineRewardButton:AddListener()
    self:FreshStatus()
    if not self.isEnter then
        self.isEnter = true
        if Events.DisconnectAll then
            Events.DisconnectAll("ONLINE_REWARD_BUTTON_EVENT")
        end
        self.handler = Events.AddListener("ONLINE_REWARD_BUTTON_EVENT", function()
            self:GetNextData()
            self:FreshStatus()
        end)
        ---@type Engine.Modules.CDTimerModule
        local cdTimerModule = CDTimerModule.GetInstance()
        if not isNull(self.countdown) then
            cdTimerModule:RemoveCD(self.countdown)
            self.countdown = nil
        end
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        ---@type PlayerDojo
        local playerDojo = playerComponent.playerDojo
        self:GetNextData()

        self.countdown = cdTimerModule:AddCD(1, function(count, id, Elapsed)
            local unlockStatus = checkNumber(playerDojo.onlineTaskInfo.unlockStatus)
            local taskList = checkTable(playerDojo.onlineTaskInfo.taskList)
            if unlockStatus == 1 and #taskList > 0 and self.targetDojo then
                ---存在合理数据时才进行倒计时
                local status = checkNumber(self.targetDojo.status)
                if status == 0 and checkNumber(self.targetDojo.type) == 1 then
                    if self.targetDojo then
                        local t = checkNumber(self.targetDojo.targetNum) - checkNumber(self.targetDojo.progress)
                        t = math.max(0, t)
                        CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS(t))
                        if t <= 0 then
                            CfUtils.SetActive(self.UIFX_Receive, t == 0)
                            CfUtils.SetActive(self.redPoint, t == 0)
                            CfUtils.SetActive(self.TextTime.transform.parent, t > 0)
                        end
                    end
                end
            end
        end, CountDownTime, false, true)
    end
end

function OnlineRewardButton:FreshStatus()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent == nil then
        return
    end
    local isShow = playerComponent:IsOpenOnlineRewards()
    CfUtils.SetActive(self.trans.gameObject, isShow)
end

function OnlineRewardButton:RemoveListener()
    self.isEnter = false
    ---@type Engine.Modules.CDTimerModule
    local cdTimerModule = CDTimerModule.GetInstance()
    if not isNull(self.countdown) then
        cdTimerModule:RemoveCD(self.countdown)
        self.countdown = nil
    end
    Events.RemoveListener("ONLINE_REWARD_BUTTON_EVENT", self.handler)
    self.handler = nil
end

function OnlineRewardButton:OnDestroy()
    self:RemoveListener()
    self.trans = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return OnlineRewardButton